sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var wardHospitalId = current.getValue('hospital');
    if (!wardHospitalId) return;

    if (!current.department.nil()) {
        var deptHospitalId = current.department.hospital.toString();

        if (deptHospitalId && deptHospitalId !== wardHospitalId) {
            gs.addErrorMessage('Validation Failed: The selected Department does not belong to the selected Hospital.');
            current.setAbortAction(true);
            return;
        }
    }

    if (!current.floor.nil()) {
        var hospitalName = (current.hospital.name.toString() || '').trim();
        var hospitalRootLocId = current.hospital.parent.toString() || wardHospitalId;

        // Traverse up the cmn_location hierarchy (Floor -> Block -> Hospital Root)
        var currLoc = current.floor.getRefRecord();
        while (currLoc && currLoc.isValidRecord() && !currLoc.parent.nil()) {
            currLoc = currLoc.parent.getRefRecord();
        }

        var floorRootLocId = currLoc && currLoc.isValidRecord() ? currLoc.getUniqueValue() : '';
        var floorRootLocName = currLoc && currLoc.isValidRecord() ? (currLoc.getValue('name') || '').trim() : '';
        var floorFullName = current.floor.full_name ? current.floor.full_name.toString() : '';

        var isFloorValid = false;

        // Check A: Root Location sys_id matches the hospital's root location
        if (floorRootLocId && hospitalRootLocId && floorRootLocId === hospitalRootLocId) {
            isFloorValid = true;
        }
        // Check B: Root Location name matches Hospital name OR floor full_name path starts with Hospital name
        else if (hospitalName && (floorRootLocName === hospitalName || floorFullName.indexOf(hospitalName) === 0)) {
            isFloorValid = true;
        }

        if (!isFloorValid) {
            gs.addErrorMessage('Validation Failed: The selected Floor does not belong to the selected Hospital campus.');
            current.setAbortAction(true);
            return;
        }
    }

})(current, previous);
